actions.script:
import groovy.json.JsonSlurper
import groovy.json.JsonOutput

// 🎯 DEBUG 1: Trace what the AI Agent passed into the service
ec.logger.info("🚀 [TOOL EXECUTION] add#FormField called with: targetNodeId=${targetNodeId}, label=${label}, encrypt=${encrypt}")
// 1. Enforce Domain Rule: HIPAA Sensitive Data Auto-Encryption
boolean secureField = "true".equalsIgnoreCase(encrypt)
String cleanName = label.replaceAll("\\s+", "")

// 2. Load the persistent Meta-JSON Source of Truth
// For now, we simulate pulling the current canvas buffer state.
// In production, this pulls from your active file/database entity.
String currentMetaJsonStr = context.activeLayoutBuffer ?: "{ \"id\": \"root\", \"tagName\": \"form\", \"children\": [] }"
ec.logger.info("[ADD#FORMFIELD] context.activeLayoutBuffer : ${context.activeLayoutBuffer}")
Map layoutTree = new JsonSlurper().parseText(currentMetaJsonStr)

// Build out the target child layout descriptor
Map dynamicFieldNode = [
    id: java.util.UUID.randomUUID().toString(),
    tagName: "field",
    attributes: [ name: cleanName, label: label, encrypt: secureField ? "true" : "false" ]
]

// 🎯 Call the decoupled tree mutation engine
Map mutationResult = ec.service.sync().name("org.moqui.ai.mcp.LayoutServices.mutate#JsonTree")
    .parameters([layoutTree: layoutTree, targetNodeId: targetNodeId, action: "APPEND", payloadNode: dynamicFieldNode])
    .call()

if (mutated) {
    // 🎯 DEBUG 2: Confirm successful tree modification
    ec.logger.info("🌲 [TOOL MUTATION SUCCESS] Node surgically injected under parent: ${targetNodeId}")
    String updatedMetaJson = JsonOutput.toJson(layoutTree)

    // 5. Persist the updated string back to the server storage layer here
    // e.g., ec.service.sync().name("update#LayoutAsset").parameter("metaJson", updatedMetaJson).call()

    // 🎯 FIX: Serialize the packet to text and call sendWebSocketText
    String jsonPacket = groovy.json.JsonOutput.toJson([
        event: "artifact-state-mutated",
        mutatedTree: layoutTree
    ])

    // 🎯 DEBUG 3: Inspect the final string output payload right before shipping
    ec.logger.info("📡 [NOTIFICATION BROADCAST] Shipping JSON packet to topic 'agi-ide-canvas': ${jsonPacket}")
    ec.makeNotificationMessage()
        .topic("agi-ide-workspace")
        .message(jsonPacket)
        .send()
    context.status = "SUCCESS"
} else {
    // 🎯 DEBUG 4: Trace mapping failures clearly
    ec.logger.warn("❌ [TOOL MUTATION FAILED] Target node container [${targetNodeId}] was NOT found in the active tree buffer.")
    ec.logger.warn("Target node container [${targetNodeId}] not found in Meta-JSON layout tree.")
    context.status = "NODE_NOT_FOUND"
}

ec.logger.info("[TOOL MUTATION] layoutTree: ${layoutTree}")
ec.logger.info("[TOOL MUTATION] targetNodeId: ${targetNodeId}")
ec.logger.info("[TOOL MUTATION] action: ${action}")
ec.logger.info("[TOOL MUTATION] payloadNode: ${payloadNode}")
def processNode
processNode = { Map node ->
    ec.logger.info("[TOOL MUTATION] node(1): ${node}")
    // 🎯 ROBUST ROOT/NODE ID MATCHING
    // Checks if node.id matches, node.mariaId matches exactly, or ends with the target ID suffix (#root)
    boolean isTarget = (node.id == targetNodeId) || 
                       (node.mariaId == targetNodeId) || 
                       (node.mariaId?.toString()?.endsWith("#" + targetNodeId))

    ec.logger.info("[TOOL MUTATION] isTarget: ${isTarget}")
    if (isTarget) {
        switch (action) {
            case "APPEND":
                // Adapt gracefully to either a "widgets" structure or a standard "children" layout array
                if (node.widgets != null) {
                    node.widgets.add(payloadNode)
                } else {
                    if (node.children == null) node.children = []
                    node.children.add(payloadNode)
                }
                return true
            case "REPLACE":
                node.clear()
                node.putAll(payloadNode)
                return true
        }
    }
    ec.logger.info("[TOOL MUTATION] node(2): ${node}")

    // Recursive array scanning block supporting both design idioms
    def childList = node.widgets ?: node.children
    ec.logger.info("[TOOL MUTATION] childList: ${childList}")
    if (childList && childList instanceof List) {
        if (action == "DELETE") {
            boolean removed = childList.removeIf { 
                it.id == targetNodeId || it.mariaId == targetNodeId || it.mariaId?.toString()?.endsWith("#" + targetNodeId)
            }
            if (removed) return true
        }
        for (child in childList) {
            if (child instanceof Map && processNode(child as Map)) return true
        }
    }
    return false
}
context.mutated = processNode(layoutTree)
